head.script:
scwin.checkPlaceHolder = function() {
    var is_ie89 = navigator.appVersion.indexOf("MSIE 8.") != -1 ||
        navigator.appVersion.indexOf("MSIE 9.") != -1;
    if (is_ie89) {
        return WebSquare.wUnit.getJq('#input1').val() == "프로퍼티" && WebSquare.wUnit.getJq('#input2').val() == "API";
    } else {
        return WebSquare.wUnit.getJq("#input1").attr("placeholder") == "프로퍼티" && WebSquare.wUnit.getJq("#input2").attr("placeholder") == "API";
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Property 탭 또는 Source 탭에서 input1 의 placeholder 를 확인한다.
    //1. In the Property tab or Source tab, check the placeholder for input1.
    //Verify step 1. placeholder="프로퍼티"
    //1. placeholder = "property"
    //Test step 2. input2 의 placeholder 를 확인한다.
    //2. Check the placeholder of input2.
    //Verify step 2. placeholder=""
    //2. placeholder = ""
    //Test step 3. 브라우저에서 input1 과 input2 의 placeholder 를 확인한다.
    //3. Check the placeholders for input1 and input2 in the browser.
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. input1 = 프로퍼티 / input2 = API
    //3. input1 = property / input2 = API
    WebSquare.wUnit.addCommand("assert", "scwin.checkPlaceHolder()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    input2.setPlaceholder("API");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
